-- ============================================================================
-- Sprint M21.02 · Update builtin SKILL: notarial_poder_especial_co
-- ============================================================================
-- Mejoras Pre-Sprint:
--   1. Agregar mención explícita del Art. 2158 CC (regla de mandato general)
--   2. Expandir blacklist de citas prohibidas con Ley 1996/2019 y Ley 1306/2009
--   3. Description "pushy" indicando cuándo trigger (vs poder_general)
--   4. Risk warnings adicionales
--   5. Sección "Notas para el otorgante" como UX final
--
-- Idempotente: UPDATE en versión 1 existente.
-- ============================================================================

begin;

update firm_skills set
    description = 'Poder Especial notarial colombiano. USAR cuando el usuario pide poder para un asunto ESPECÍFICO Y PUNTUAL: gestión ante una entidad concreta, venta de UN inmueble determinado, representación en UN trámite particular. Si el caso es amplio/general (administración + disposición sobre patrimonio en general), usar poder_general en su lugar. Régimen: Arts. 2142 ss. CC + Decreto 960/1970 NO Art. 74 CGP (judicial). Cita Art. 2158 CC para justificar enumeración expresa de facultades.',
    frontmatter = '{"name": "notarial_poder_especial_co", "description": "Poder Especial notarial CO · USAR cuando el caso es PUNTUAL (un trámite, un inmueble, una entidad). Para casos amplios/generales con disposición sobre patrimonio, usar notarial_poder_general_co. Régimen: Arts. 2142 ss. CC + Decreto 960/1970. NO usar Art. 74 CGP (es judicial). MAX 5 verify_citation.", "category": "notarial", "doc_family": "notarial_poder", "doc_type": "poder_especial", "default_scope": "doc_type", "language": "es-CO", "jurisdiction": "CO", "version": "1.0.1", "tier": "public", "sources": ["https://www.suin-juriscol.gov.co/viewDocument.asp?ruta=Decretos/1058919", "https://www.secretariasenado.gov.co/senado/basedoc/codigo_civil.html", "https://www.notariado.org.co/portal"]}'::jsonb,
    system_prompt = E'# Poder Especial Notarial — Colombia (v1.0.1)\n\n## When to use\n\nUsar este SKILL cuando el usuario solicita un poder para un asunto ESPECÍFICO Y PUNTUAL ante notaría. Ejemplos:\n\n- Poder para vender UN inmueble determinado (con dirección, matrícula)\n- Poder para representación ante UNA entidad específica (DIAN, ICA, EPS, EAAB)\n- Poder corporativo para representante legal en gestión puntual\n- Poder para firmar facilidad de pago / acuerdo comercial específico\n\n**Diferencia vs `notarial_poder_general_co`:**\n- ESPECIAL → asunto puntual + facultades específicas para ese asunto.\n- GENERAL → facultades amplias sobre la generalidad de bienes/negocios.\n\nSi el usuario dice "poder amplio y suficiente" sin especificar un asunto puntual, usar `notarial_poder_general_co`.\n\n**NO usar este SKILL para:**\n- Poder para actuar en proceso judicial → usar `judicial_poder_apoderado_judicial_co` (Art. 74 CGP).\n- Poder general (todas las facultades amplias) → usar `notarial_poder_general_co`.\n- Revocatoria de poder → usar `notarial_revocatoria_poder_co`.\n\n## Document Structure (orden estricto)\n\n1. **Título**: PODER ESPECIAL (centrado, bold, MAYÚSCULAS)\n2. **Subtítulo italic**: "(Otorgado por persona natural / representante legal de persona jurídica)"\n3. **Destinatario notarial**: "Señor(a) Notario(a) [NUMERO_NOTARIA] del Círculo de [CIUDAD]" + "E. S. D."\n4. **Comparecencia del poderdante** (párrafo único justificado)\n5. **Designación del apoderado** (párrafo único)\n6. **PRIMERA. OBJETO DEL PODER** (qué asunto específico)\n7. **SEGUNDA-N. FACULTADES ESPECÍFICAS** (numeradas en ordinal, cada una con verbo de acción claro)\n8. **PENÚLTIMA. NATURALEZA Y FUNDAMENTO LEGAL** (Arts. 2142 ss. CC + Art. 2158 CC para justificar enumeración + Decreto 960/1970)\n9. **N. VIGENCIA Y REVOCABILIDAD** (Arts. 2189 ss. CC)\n10. **N+1. ACEPTACIÓN EXPRESA DEL APODERADO**\n11. **Lugar, fecha y firmas** (EL PODERDANTE + EL APODERADO ACEPTO)\n12. **Diligencia notarial de autenticación**\n13. **Notas para el otorgante** (marcadas para eliminar antes de firmar)\n\n## Style Conventions\n\n### Encabezado\n```\n                    PODER ESPECIAL\n       (Otorgado por representante legal de persona jurídica)\n\n\nSeñor(a) Notario(a) [NUMERO_NOTARIA] del Círculo de [CIUDAD]\nE. S. D.\n```\n\n### Comparecencia (fórmula notarial estándar)\n"Yo, **[NOMBRE COMPLETO EN MAYÚSCULAS]**, mayor de edad, vecino(a) de **[CIUDAD]**, identificado(a) con cédula de ciudadanía No. **[NÚMERO]** expedida en **[LUGAR]**, [obrando en mi propio nombre / obrando en mi calidad de [CALIDAD] de la sociedad [RAZÓN_SOCIAL], identificada con NIT [NIT]…], manifiesto que mediante el presente documento confiero **PODER ESPECIAL, AMPLIO Y SUFICIENTE**, al señor:"\n\n### Cláusulas (numeración OBLIGATORIA en ordinales)\n- PRIMERA. OBJETO DEL PODER\n- SEGUNDA. FACULTAD PARA [acción específica del asunto puntual]\n- TERCERA. FACULTAD PARA [acción específica]\n- …\n- CUARTA. NATURALEZA Y FUNDAMENTO\n- QUINTA. VIGENCIA Y REVOCABILIDAD\n- SEXTA. ACEPTACIÓN DEL APODERADO\n\n## Citas normativas OBLIGATORIAS (whitelist)\n\n- **Arts. 2142 y siguientes del Código Civil** — régimen del mandato.\n- **Art. 2158 del Código Civil** ⭐ — "Los términos generales del mandato no se extienden a otra cosa que a los actos de administración… Para hipotecar, enajenar, transigir y demás actos que no sean de mera administración, se requiere poder especial." Esta es la justificación para enumerar facultades específicas.\n- **Decreto 960 de 1970** — Estatuto del Notariado (autenticación, presentación personal).\n- **Arts. 2189 y siguientes del Código Civil** — si se incluye cláusula de revocabilidad.\n- Si compromete patrimonio empresarial: **Art. 196 del Código de Comercio** — restricciones estatutarias.\n\n## Citas PROHIBIDAS (blacklist — errores comunes)\n\nEstas citas son ERRORES recurrentes que invalidan el documento o llevan al usuario a confusión:\n\n- ❌ **Art. 74 CGP** (Ley 1564/2012) → es para poderes JUDICIALES (apoderado en proceso ante juez). El régimen notarial es CC + Decreto 960/1970.\n- ❌ **Art. 836 CGP** → NO existe (el CGP llega al Art. 627).\n- ❌ **Citar el CGP en general** en un poder notarial → régimen equivocado.\n- ❌ **Ley 1996 de 2019** → sobre capacidad legal de personas con discapacidad (eliminación de interdicción + acuerdos de apoyo). NO aplica a poderes ordinarios.\n- ❌ **Ley 1306 de 2009** → sobre protección de personas con discapacidad mental. NO aplica a poderes ordinarios.\n- ❌ **Decreto 2148 de 1983** → derogado por Decreto 960/1970 (verificar siempre vigencia con check_derogation antes de citar decretos antiguos).\n\n## Common Placeholders\n\n| Placeholder | Tipo | Ejemplo |\n|---|---|---|\n| `[NOMBRE_PODERDANTE]` | string MAYÚSCULAS | LAURA ALEJANDRA ALZATE RESTREPO |\n| `[CC_PODERDANTE]` | número formato CO | 1.017.207.731 |\n| `[CIUDAD_EXPEDICION_CC_PODERDANTE]` | string | Medellín |\n| `[RAZON_SOCIAL]` | string | CONSTRUCTORA XYZ S.A.S. |\n| `[NIT]` | número con DV | 900.123.456-7 |\n| `[MATRICULA_MERCANTIL]` | string | 12345678 |\n| `[CAMARA_COMERCIO]` | string | Medellín para Antioquia |\n| `[NOMBRE_APODERADO]` | string MAYÚSCULAS | CAMILO ANDRÉS MAYORGA GARCÍA |\n| `[CC_APODERADO]` | número | 8.028.112 |\n| `[CIUDAD_EXPEDICION_CC_APODERADO]` | string | Medellín |\n| `[PROFESION_APODERADO]` | string | Ingeniero, Abogado, etc. |\n| `[DIRECCION_APODERADO]` | string | Cra 70 # 45-23 |\n| `[CORREO_APODERADO]` | email | apoderado@example.com |\n| `[OBJETO_ESPECIFICO]` | string | "venta del inmueble de matrícula 50C-123456" |\n| `[TOPE_MAXIMO_CUANTIA]` | monetario | hasta $50.000.000 (cincuenta millones M/cte) |\n| `[VIGENCIA_MESES]` | número | 6 |\n| `[NOTARIA_DESTINATARIA]` | string | Notaría 21 |\n| `[DIA]`, `[MES]`, `[ANIO]` | tokens fecha | (separados para fechas notariales) |\n\n## docx-js Style Hints\n\n- Page: US Letter (12240 × 15840 DXA), 1" margins (1440 DXA each side)\n- Font default: Arial 11pt (`size: 22`)\n- **Heading1** (cláusulas): `size: 26, bold, spacing: { before: 240, after: 200 }`\n- **Title** (PODER ESPECIAL): centered, bold, `size: 30`\n- **Subtitle**: italic centered, `size: 20`\n- **Placeholders** [X]: shading `FFF2CC` (yellow), bold inline\n- **Body paragraphs**: alignment JUSTIFIED, line spacing 1.15\n- **Signature lines**: `_____________________________________` (40 chars)\n\n## Cierre / Firmas\n\n```\nEL PODERDANTE,\n\n_________________________________________\n[NOMBRE_PODERDANTE en bold]\nC.C. No. [CC_PODERDANTE] de [LUGAR]\n[Si persona jurídica:] Representante Legal de [RAZON_SOCIAL] — NIT [NIT]\nCorreo: [CORREO]  /  Cel.: [CELULAR]\n\n\nEL APODERADO (ACEPTO),\n\n_________________________________________\n[NOMBRE_APODERADO en bold]\nC.C. No. [CC_APODERADO] de [CIUDAD_EXPEDICION_CC_APODERADO]\nCorreo: [CORREO_APODERADO]\n```\n\n## Diligencia Notarial (sección final OBLIGATORIA)\n\n```\nDILIGENCIA NOTARIAL DE AUTENTICACIÓN / PRESENTACIÓN PERSONAL\n\n(Espacio reservado para la Notaría [___] del Círculo de [CIUDAD].\nLa nota notarial dará fe de la presentación personal y/o reconocimiento\nde contenido y firma del poderdante, conforme al Estatuto Notarial.)\n\nFecha: ________________   Escritura/Acta No.: ________________\n\nFirma y sello del Notario: ______________________________\n```\n\n## Risk Warnings (incluir como advertencia en MAYÚSCULAS antes de firmas)\n\n1. **Falta tope máximo de cuantía** (para poderes que comprometen patrimonio):\n```\n⚠ ADVERTENCIA — TOPE MÁXIMO DE CUANTÍA NO ESTABLECIDO\nSin tope máximo, esta facultad es de ALTO RIESGO LEGAL. Se recomienda\nNO autenticar este poder hasta fijar un monto específico en pesos y\nen letras.\n```\n\n2. **Persona jurídica + restricciones estatutarias no verificadas**:\n```\n⚠ ADVERTENCIA — RESTRICCIONES ESTATUTARIAS\nEl ejercicio de las facultades queda sujeto a las restricciones que\nlos estatutos sociales impongan. Si requieren autorización previa de\njunta directiva o asamblea, dicha autorización debe obtenerse y\nacreditarse (Art. 196 CCo).\n```\n\n3. **Garantías sobre inmuebles**:\n```\n⚠ NOTA — ESCRITURA PÚBLICA REQUERIDA\nPara constituir garantía sobre bienes inmuebles, el apoderado deberá\nconcurrir al otorgamiento de la respectiva escritura pública y posterior\nregistro en la Oficina de Registro de Instrumentos Públicos.\n```\n\n4. **Apoderado NO es abogado y objeto incluye representación judicial**:\n```\n⚠ ERROR — APODERADO NO HABILITADO PARA REPRESENTACIÓN JUDICIAL\nLa representación en procesos judiciales SOLO puede ejercerla un\nabogado titulado e inscrito (Art. 74 CGP). Si esa es la finalidad,\notorgar poder especial judicial distinto.\n```\n\n## Notas para el otorgante (sección final del documento generado)\n\nIncluir AL FINAL del documento como sección clara "Notas para el otorgante — eliminar antes de firmar":\n\n1. **Carácter especial vs general**: este poder es ESPECIAL para el asunto puntual descrito en la Cláusula PRIMERA. Si necesita poder amplio para administrar y disponer de bienes en general, otorgar un poder GENERAL distinto.\n\n2. **Autenticación notarial**: presentarse personalmente ante notaría con cédula original. La firma del poderdante debe autenticarse o el documento elevarse a escritura pública (según el acto encomendado).\n\n3. **Inmuebles**: cualquier acto sobre inmuebles requiere escritura pública y registro adicionales. Este poder habilita al apoderado a comparecer, no sustituye el acto principal.\n\n4. **Vigencia**: definir plazo o dejar indefinido. La revocatoria debe comunicarse al apoderado y a los terceros relevantes.\n\n5. **Persona jurídica**: si el poderdante es sociedad, anexar Certificado de Existencia y Representación Legal vigente (≤ 30 días).\n\n6. **Asesoría**: este es un modelo de orientación general y NO constituye asesoría legal específica. Antes de firmar, hacerlo revisar por un abogado o por la notaría.\n\n## Bibliography\n\n1. **Decreto 960 de 1970** — Estatuto del Notariado y del Registro\n   https://www.suin-juriscol.gov.co/viewDocument.asp?ruta=Decretos/1058919\n2. **Código Civil** Arts. 2142-2199 (Mandato)\n   https://www.secretariasenado.gov.co/senado/basedoc/codigo_civil.html\n3. **Código de Comercio** Arts. 196-198 (Representación de sociedades)\n   https://www.secretariasenado.gov.co/senado/basedoc/codigo_comercio.html\n4. **Unión Colegiada del Notariado Colombiano**\n   https://www.notariado.org.co/portal\n5. **Superintendencia de Notariado y Registro** — circulares\n   https://www.supernotariado.gov.co',
    version = 1,
    status = 'published',
    metadata = '{"seeded_by":"sprint_m1927","seed_date":"2026-05-28","updated_by":"sprint_m2102","updated_date":"2026-06-03","update_notes":"agregar Art 2158 CC + blacklist Ley 1996/2019 + Ley 1306/2009 + notas otorgante + pushy description"}'::jsonb,
    updated_at = now()
where firm_id is null
  and command = '/redactar/poder-especial'
  and version = 1;

-- Verificación
do $$
declare v_count int;
begin
  select count(*) into v_count from firm_skills
   where firm_id is null
     and command = '/redactar/poder-especial'
     and status = 'published'
     and system_prompt like '%Art. 2158 del C%digo Civil%';
  if v_count = 0 then
    raise exception 'M21.02 update poder-especial: Art. 2158 NOT FOUND in system_prompt after update';
  end if;
  raise notice 'M21.02 poder-especial updated successfully (Art. 2158 CC present, blacklist expanded)';
end$$;

commit;
